installation.script:
#!/bin/bash
# Node-RED: picks the Node-RED version from the npm registry and writes it
# to package.json; the server installs it with npm when it starts, for the
# Node.js version it runs. The data folder (flows, credentials, nodes
# added from the palette, settings.js) is never touched once there.
set -euo pipefail
cd /mnt/server
fail() { echo "$1"; exit 1; }

meta=$(curl -fsS --retry 3 -A "raptor-installer (+https://raptorpanel.net)" https://registry.npmjs.org/node-red) ||
    fail "The npm registry can't be reached right now. Reinstall to try again."
latest=$(jq -r '."dist-tags".latest' <<<"$meta")
version="${VERSION:-latest}"
version="${version#v}"
[ "$version" = latest ] && version="$latest"
jq -e --arg v "$version" '.versions[$v]' <<<"$meta" >/dev/null ||
    fail "Node-RED has no version $version. Set Version to latest, or to a release such as $latest, then reinstall."
node=$(jq -r --arg v "$version" '.versions[$v].engines.node // ""' <<<"$meta")

# package.json lists only Node-RED; nodes added in the editor go in data/.
if [ -f package.json ]; then
    jq --arg v "$version" '.dependencies["node-red"] = $v' package.json > package.json.new
else
    jq -n --arg v "$version" '{name: "node-red-server", private: true, dependencies: {"node-red": $v}}' > package.json.new
fi
mv -f package.json.new package.json

mkdir -p data
if [ ! -f data/settings.js ]; then
    cat > data/settings.js <<'JS'
// Node-RED's settings: https://nodered.org/docs/user-guide/runtime/settings-file
// The port and the editor's login come from the server's settings. Restart
// the server after changing this file.
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");

// The editor runs any code a flow holds, so it always needs a login: the
// server's Admin password, or a random one kept in admin-password.txt.
const user = process.env.ADMIN_USERNAME || "admin";
let password = process.env.ADMIN_PASSWORD || "";
if (!password) {
    const file = path.join(__dirname, "admin-password.txt");
    try {
        password = fs.readFileSync(file, "utf8").trim();
    } catch {
        password = crypto.randomBytes(15).toString("base64url");
        fs.writeFileSync(file, password + "\n", { mode: 0o600 });
    }
    console.log(`Log in to the editor as ${user}, with the password in data/admin-password.txt (${password}).`);
}
const same = (a, b) => {
    const x = crypto.createHash("sha256").update(String(a)).digest();
    const y = crypto.createHash("sha256").update(String(b)).digest();
    return crypto.timingSafeEqual(x, y);
};

module.exports = {
    uiHost: "0.0.0.0",
    uiPort: Number(process.env.SERVER_PORT) || 1880,
    flowFile: "flows.json",
    adminAuth: {
        type: "credentials",
        users: (name) => Promise.resolve(name === user ? { username: user, permissions: "*" } : null),
        authenticate: (name, pass) => Promise.resolve(same(name, user) && same(pass, password) ? { username: user, permissions: "*" } : null),
    },
    // Node-RED's update check asks nodered.org for new versions.
    telemetry: { enabled: process.env.UPDATE_CHECK === "1" },
    diagnostics: { enabled: true, ui: true },
    logging: { console: { level: "info", metrics: false, audit: false } },
    editorTheme: { projects: { enabled: false } },
    functionExternalModules: true,
};
JS
fi
echo "Installed Node-RED $version${node:+ (it needs Node.js $node)}."
